import{state}from"./state.js";import{renderAll}from"./ui.js";import{approveRequestOnServer,rejectRequestOnServer,deleteRequestOnServer}from"./api.js";import{showToast,showConfirm,showMobileEventNotification}from"./utils.js";import{applyServerFamilyData,checkDailyCoinLimit,checkFrequency,checkLimits,flushPendingSave}from"./action-helpers.js";import{triggerCoinBurst}from"./motion-feedback.js";function verifyPurchaseLimits(e,t,i){if(!t)return i();const r=checkLimits(t,e.moneyAmount||0,{childIdOverride:e.childId,excludeRequestId:e.id});if(r){const t=`${r}<br><br>Списать ${e.coins} <span class="gamified-icon icon-coin-stack" aria-hidden="true" style="width: 1.1rem; height: 1.1rem; vertical-align: middle;"></span>?`;showConfirm("Лимит превышен",t,{onConfirm:i})}else i()}async function commitRequestMutation(e){await flushPendingSave();const t=await e();return t.success&&t.data?(applyServerFamilyData(t.data,{currentChildId:state.currentChildId}),renderAll(),!0):(showToast(t.error||"Не удалось обновить заявку","error"),!1)}function handleApprovePurchase(e){const t=state.children.find(t=>t.id==e.childId);if(t&&t.balance<e.coins)return showToast(`Недостаточно монет у ребенка (${t.name})`,"error");const i=state.shopItems.find(t=>t.id==(e.itemId||e.taskId));verifyPurchaseLimits(e,i,()=>{commitRequestMutation(()=>approveRequestOnServer(e.id,state.currentChildId)).then(e=>{e&&triggerCoinBurst()})})}function handleApproveTask(e){const t=state.tasks.find(t=>t.id==e.taskId&&(!t.childId||t.childId==e.childId)),i=[];if(t){const r=checkFrequency(t,e.childId,e.id);r&&i.push(r)}const r=checkDailyCoinLimit(e.childId,e.coins,e.id);r&&i.push(r);const s=()=>{commitRequestMutation(()=>approveRequestOnServer(e.id,state.currentChildId)).then(t=>{t&&(showMobileEventNotification(`Заявка подтверждена: +${e.coins} мон.`,"success","Заявка подтверждена"),triggerCoinBurst())})};if(i.length>0){const t=`${i.join(". ")}<br><br>Начислить ${e.coins} <span class="gamified-icon icon-coin-stack" aria-hidden="true" style="width: 1.1rem; height: 1.1rem; vertical-align: middle;"></span>?`;showConfirm("Лимиты превышены",t,{onConfirm:s})}else s()}export function approveRequest(e){const t=state.requests.find(t=>t.id==e);if(!t)return;"shop_purchase"===t.requestType?handleApprovePurchase(t):handleApproveTask(t)}export function rejectRequest(e){const t=state.requests.find(t=>t.id==e);t&&commitRequestMutation(()=>rejectRequestOnServer(t.id,state.currentChildId)).then(e=>{e&&showToast("Заявка отклонена","info")})}export function deleteRequest(e){showConfirm("Удалить заявку?","Вы уверены, что хотите безвозвратно удалить заявку?",{onConfirm:()=>{commitRequestMutation(()=>deleteRequestOnServer(e,state.currentChildId))}})}